const { readFileSync } = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('Missing INPUT_PATH');
const content = readFileSync(inputPath, 'utf8');
globalThis.markdown = content;

const { fromMarkdown } = await import('mdast-util-from-markdown');
const { gfmTaskListItemFromMarkdown } = await import('mdast-util-gfm-task-list-item');
const { gfmTaskListItem } = await import('micromark-extension-gfm-task-list-item');
const tree = fromMarkdown(globalThis.markdown, {
  extensions: [gfmTaskListItem],
  mdastExtensions: [gfmTaskListItemFromMarkdown()]
});
globalThis.astJson = JSON.stringify(tree);
